def metrics(residents, p):
    x = y = z = 0
    for e in residents:
        if e is p:
            continue
        if e['rank'] < p['rank']:
            x += 1
        elif e['rank'] > p['rank']:
            z += 1
        else:
            if e['ord'] < p['ord']:
                y += 1
    return x, y, z
